import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{r as i,o as n,c as s,a as t,e as y,w as f,f as l,b as e}from"./app-7d619fc9.js";const x={},g=l('<p>按首次定义的篇目排序。每条给出中文术语、英文原文、一句话解释，以及在贯穿例子中的所指。正式定义以所在篇目为准，这里只帮助回忆。</p><h2 id="第-01-篇-状态、抽象与近似" tabindex="-1"><a class="header-anchor" href="#第-01-篇-状态、抽象与近似" aria-hidden="true">#</a> 第 01 篇：状态、抽象与近似</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">具体状态</td><td style="text-align:left;">concrete state</td><td style="text-align:left;">某次真实执行在某个时刻的全部信息</td><td style="text-align:left;"><code>flag=true, x=&quot;alice&quot;, y=&quot;alice&quot;</code></td></tr><tr><td style="text-align:left;">抽象状态</td><td style="text-align:left;">abstract state</td><td style="text-align:left;">分析实际保存的、概括了一组具体状态的记号</td><td style="text-align:left;"><code>{x,y}</code>：x、y 都可能有污点</td></tr><tr><td style="text-align:left;">抽象域</td><td style="text-align:left;">abstract domain</td><td style="text-align:left;">分析允许写下的全部抽象状态的集合</td><td style="text-align:left;"><code>𝒫({x,y})</code> 的四个元素</td></tr><tr><td style="text-align:left;">事实</td><td style="text-align:left;">fact</td><td style="text-align:left;">抽象状态中的一个原子条目</td><td style="text-align:left;"><code>x</code> 表示“x 可能有污点”</td></tr><tr><td style="text-align:left;">γ（具体化）</td><td style="text-align:left;">concretization</td><td style="text-align:left;">一个抽象状态所“放行”的全部具体状态</td><td style="text-align:left;"><code>γ({x})</code> 不含任何 y 有污点的状态</td></tr><tr><td style="text-align:left;">转移函数</td><td style="text-align:left;">transfer function</td><td style="text-align:left;">一条语句怎样把执行前的抽象状态变成执行后的</td><td style="text-align:left;"><code>y=x</code>：删旧 y，若含 x 则加 y</td></tr><tr><td style="text-align:left;">控制流汇合</td><td style="text-align:left;">control-flow merge / join point</td><td style="text-align:left;">多条执行路线到达同一位置</td><td style="text-align:left;">if 语句之后的 <code>sink(y)</code></td></tr><tr><td style="text-align:left;">过近似</td><td style="text-align:left;">over-approximation</td><td style="text-align:left;">结果覆盖全部真实行为，允许多算</td><td style="text-align:left;">报告 y 可能有污点，即使某些路径上没有</td></tr><tr><td style="text-align:left;">欠近似</td><td style="text-align:left;">under-approximation</td><td style="text-align:left;">结果只含真实行为，允许漏算</td><td style="text-align:left;">只探索 flag=false 一条路径</td></tr><tr><td style="text-align:left;">可靠</td><td style="text-align:left;">sound</td><td style="text-align:left;">在规定模型下结果覆盖真实行为，不漏报</td><td style="text-align:left;"><code>R ⊆ γ(S)</code></td></tr><tr><td style="text-align:left;">精确度</td><td style="text-align:left;">precision</td><td style="text-align:left;">结果排除了多少不可能的情况</td><td style="text-align:left;"><code>{x}</code> 比 <code>{x,y}</code> 精确</td></tr><tr><td style="text-align:left;">误报 / 漏报</td><td style="text-align:left;">false positive / false negative</td><td style="text-align:left;">报告了不存在的问题 / 遗漏了真实问题</td><td style="text-align:left;">用 <code>{x,y}</code> 进入 <code>if(!flag) sink(y)</code> 是误报</td></tr><tr><td style="text-align:left;">路径敏感</td><td style="text-align:left;">path-sensitive</td><td style="text-align:left;">分析区分不同分支条件下的状态</td><td style="text-align:left;">分别保存 <code>(flag=true, {x,y})</code> 与 <code>(flag=false, {x})</code></td></tr><tr><td style="text-align:left;">may / must</td><td style="text-align:left;">may / must analysis</td><td style="text-align:left;">事实“可能成立”还是“所有路径都成立”</td><td style="text-align:left;">可能有污点 / 保证已初始化</td></tr></tbody></table><h2 id="第-02-篇-编译流程与分析工具" tabindex="-1"><a class="header-anchor" href="#第-02-篇-编译流程与分析工具" aria-hidden="true">#</a> 第 02 篇：编译流程与分析工具</h2>',4),r=t("table",null,[t("thead",null,[t("tr",null,[t("th",{style:{"text-align":"left"}},"术语"),t("th",{style:{"text-align":"left"}},"英文"),t("th",{style:{"text-align":"left"}},"一句话解释"),t("th",{style:{"text-align":"left"}},"在例子中")])]),t("tbody",null,[t("tr",null,[t("td",{style:{"text-align":"left"}},"中间表示"),t("td",{style:{"text-align":"left"}},"IR, intermediate representation"),t("td",{style:{"text-align":"left"}},"编译器或分析器内部使用的程序形式"),t("td",{style:{"text-align":"left"}},"Jimple")]),t("tr",null,[t("td",{style:{"text-align":"left"}},"抽象语法树"),t("td",{style:{"text-align":"left"}},"AST, abstract syntax tree"),t("td",{style:{"text-align":"left"}},"按源码语法结构组织的树"),t("td",{style:{"text-align":"left"}},"Clang 前端的输出")]),t("tr",null,[t("td",{style:{"text-align":"left"}},"Jimple"),t("td",{style:{"text-align":"left"}},"—"),t("td",{style:{"text-align":"left"}},"Soot 的有类型三地址中间表示"),t("td",{style:{"text-align":"left"}},[t("code",null,"y = x;"),e("、"),t("code",null,"if flag == false goto n6;")])]),t("tr",null,[t("td",{style:{"text-align":"left"}},"控制流图"),t("td",{style:{"text-align":"left"}},"CFG, control-flow graph"),t("td",{style:{"text-align":"left"}},"节点是语句或基本块，边是可能的执行转移"),t("td",{style:{"text-align":"left"}},"n1…n7 与 n4→n5、n4→n6")]),t("tr",{"n1…n4":""},[t("td",{style:{"text-align":"left"}},"基本块"),t("td",{style:{"text-align":"left"}},"basic block"),t("td",{style:{"text-align":"left"}},"只能从块首进入、块末离开的连续语句"),t("td",{style:{"text-align":"left"}},"B1=")]),t("tr",null,[t("td",{style:{"text-align":"left"}},"字节码"),t("td",{style:{"text-align":"left"}},"bytecode"),t("td",{style:{"text-align":"left"}},"JVM 执行的指令序列"),t("td",{style:{"text-align":"left"}},[t("code",null,"aload_1; astore_2"),e(" 对应 "),t("code",null,"y=x")])]),t("tr",null,[t("td",{style:{"text-align":"left"}},"三地址码"),t("td",{style:{"text-align":"left"}},"three-address code"),t("td",{style:{"text-align":"left"}},"将复杂表达式拆成简单操作，典型语句含一个运算、至多三个地址"),t("td",{style:{"text-align":"left"}},[t("code",null,"t = a + b"),e("；调用可有多个实参")])]),t("tr",null,[t("td",{style:{"text-align":"left"}},"操作数栈"),t("td",{style:{"text-align":"left"}},"operand stack"),t("td",{style:{"text-align":"left"}},"JVM 暂存中间值的栈，字节码指令在其上取放数据"),t("td",{style:{"text-align":"left"}},[t("code",null,"input()"),e(" 的返回值先在栈上，再 "),t("code",null,"astore_1")])]),t("tr",null,[t("td",{style:{"text-align":"left"}},"构建捕获"),t("td",{style:{"text-align":"left"}},"build capture"),t("td",{style:{"text-align":"left"}},"包裹构建命令、监控每次编译器调用以取得真实编译上下文"),t("td",{style:{"text-align":"left"}},[e("Coverity 的 "),t("code",null,"cov-build")])])])],-1),o=l('<h2 id="第-03-篇-数据流分析与格" tabindex="-1"><a class="header-anchor" href="#第-03-篇-数据流分析与格" aria-hidden="true">#</a> 第 03 篇：数据流分析与格</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">IN / OUT</td><td style="text-align:left;">in-set / out-set</td><td style="text-align:left;">每个节点语句执行前 / 后的抽象状态</td><td style="text-align:left;"><code>IN[n6]={x,y}</code></td></tr><tr><td style="text-align:left;">向前分析</td><td style="text-align:left;">forward analysis</td><td style="text-align:left;">信息沿执行方向从前驱流向后继</td><td style="text-align:left;">污点从 input 流向 sink</td></tr><tr><td style="text-align:left;">可达标记</td><td style="text-align:left;">reachability flag</td><td style="text-align:left;">区分“没执行到”与“执行到了但集合为空”</td><td style="text-align:left;">入口可达且 IN=∅</td></tr><tr><td style="text-align:left;">偏序</td><td style="text-align:left;">partial order</td><td style="text-align:left;">自反、反对称、传递的比较关系，允许有元素不可比</td><td style="text-align:left;">本系列 <code>a ⊑ b</code> 表示 a 至少和 b 一样精确</td></tr><tr><td style="text-align:left;">全序</td><td style="text-align:left;">total order</td><td style="text-align:left;">任意两个元素都可比较的偏序</td><td style="text-align:left;">整数上的 <code>≤</code></td></tr><tr><td style="text-align:left;">幂集</td><td style="text-align:left;">power set, 𝒫</td><td style="text-align:left;">一个集合的所有子集组成的集合</td><td style="text-align:left;"><code>𝒫({x,y})</code> 有四个元素</td></tr><tr><td style="text-align:left;">上界</td><td style="text-align:left;">upper bound</td><td style="text-align:left;">位于两个元素上方或与之相等的元素</td><td style="text-align:left;"><code>{x,y}</code> 是 <code>{x}</code>、<code>{y}</code> 的上界</td></tr><tr><td style="text-align:left;">格</td><td style="text-align:left;">lattice</td><td style="text-align:left;">任意两元素都有最小上界和最大下界的偏序集</td><td style="text-align:left;"><code>𝒫({x,y})</code></td></tr><tr><td style="text-align:left;">完全格</td><td style="text-align:left;">complete lattice</td><td style="text-align:left;">任意子集都有最小上界和最大下界的格；有限格自动满足</td><td style="text-align:left;"><code>𝒫({x,y})</code></td></tr><tr><td style="text-align:left;">Join / 最小上界</td><td style="text-align:left;">join, least upper bound, ⊔</td><td style="text-align:left;">能同时容纳两边、又不多容的最小结果</td><td style="text-align:left;">污点：并集；初始化保证：交集</td></tr><tr><td style="text-align:left;">Meet / 最大下界</td><td style="text-align:left;">meet, greatest lower bound, ⊓</td><td style="text-align:left;">Join 的对偶</td><td style="text-align:left;">污点：交集</td></tr><tr><td style="text-align:left;">⊤ / ⊥</td><td style="text-align:left;">top / bottom</td><td style="text-align:left;">格中最粗 / 最精确的元素</td><td style="text-align:left;">污点域：<code>{x,y}</code> / <code>∅</code></td></tr><tr><td style="text-align:left;">序对偶</td><td style="text-align:left;">order duality</td><td style="text-align:left;">把偏序整个反过来，Join 与 Meet 互换</td><td style="text-align:left;">其他教材把并集叫 Meet 的原因</td></tr></tbody></table><h2 id="第-04-篇-工作列表与不动点" tabindex="-1"><a class="header-anchor" href="#第-04-篇-工作列表与不动点" aria-hidden="true">#</a> 第 04 篇：工作列表与不动点</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">工作列表</td><td style="text-align:left;">worklist</td><td style="text-align:left;">等待首次计算或重新计算的节点队列</td><td style="text-align:left;"><code>[Z,S]</code></td></tr><tr><td style="text-align:left;">回边</td><td style="text-align:left;">back edge</td><td style="text-align:left;">从循环体末尾回到循环头的边</td><td style="text-align:left;">C→H</td></tr><tr><td style="text-align:left;">单调</td><td style="text-align:left;">monotone</td><td style="text-align:left;">输入按偏序变粗，输出不会变精</td><td style="text-align:left;"><code>y=&quot;safe&quot;</code> 的规则单调但会删事实</td></tr><tr><td style="text-align:left;">不动点 / 最小不动点</td><td style="text-align:left;">fixed point / least fixed point</td><td style="text-align:left;">再算一遍也不变的状态 / 其中最精确的那个</td><td style="text-align:left;">循环头稳定在 <code>{x,y,z}</code></td></tr><tr><td style="text-align:left;">上升链 / 有限高度</td><td style="text-align:left;">ascending chain / finite height</td><td style="text-align:left;">按偏序变粗的序列 / 严格上升的步数有统一上限</td><td style="text-align:left;"><code>{x} ⊑ {x,y} ⊑ {x,y,z}</code></td></tr><tr><td style="text-align:left;">FIFO / LIFO</td><td style="text-align:left;">first in, first out / last in, first out</td><td style="text-align:left;">按加入顺序 / 逆加入顺序取出待处理节点</td><td style="text-align:left;">H 依次加入 Z、S 后，FIFO 先取 Z，LIFO 先取 S</td></tr><tr><td style="text-align:left;">优先队列</td><td style="text-align:left;">priority queue</td><td style="text-align:left;">按优先级选择下一个待处理节点</td><td style="text-align:left;">固定优先级 <code>H、Z、Y、C、S</code>，让 S 晚些处理</td></tr><tr><td style="text-align:left;">逆后序</td><td style="text-align:left;">reverse postorder, RPO</td><td style="text-align:left;">深度优先遍历完成节点的记录顺序反转；无环图上是拓扑顺序</td><td style="text-align:left;">可用作向前分析的调度优先级</td></tr><tr><td style="text-align:left;">轮询迭代</td><td style="text-align:left;">round-robin iteration</td><td style="text-align:left;">按固定顺序反复计算各节点，直到完整一轮无变化</td><td style="text-align:left;">即使只有 H 变化，也会扫描一轮中的其他节点</td></tr><tr><td style="text-align:left;">混沌迭代</td><td style="text-align:left;">chaotic iteration</td><td style="text-align:left;">每次选择一个分量，使用当前最新状态更新；需保证待更新项不被遗漏</td><td style="text-align:left;">worklist 利用依赖关系安排这种迭代</td></tr><tr><td style="text-align:left;">Kildall 算法</td><td style="text-align:left;">Kildall&#39;s algorithm</td><td style="text-align:left;">在格上合并并通过待处理集合传播变化的经典数据流算法</td><td style="text-align:left;">首次到达或输入变化后继续处理后继</td></tr><tr><td style="text-align:left;">区间域</td><td style="text-align:left;">interval domain</td><td style="text-align:left;">每个变量记一个 <code>[下界, 上界]</code>；数学整数上的区间域高度无限</td><td style="text-align:left;"><code>[0,2]</code></td></tr><tr><td style="text-align:left;">加宽</td><td style="text-align:left;">widening, ∇</td><td style="text-align:left;">主动扩大结果以保证收敛；区间的一种做法是将向外移动的界推到无穷</td><td style="text-align:left;"><code>[0,1] ∇ [0,2] = [0,+∞)</code></td></tr></tbody></table><h2 id="第-05-篇-常量传播与表达式求值" tabindex="-1"><a class="header-anchor" href="#第-05-篇-常量传播与表达式求值" aria-hidden="true">#</a> 第 05 篇：常量传播与表达式求值</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">平坦格</td><td style="text-align:left;">flat lattice</td><td style="text-align:left;">底、一层互不可比的元素、顶三层结构；最长链只有三个元素</td><td style="text-align:left;"><code>⊥ ⊑ 3 ⊑ ⊤</code></td></tr><tr><td style="text-align:left;">环境</td><td style="text-align:left;">environment, ρ</td><td style="text-align:left;">变量到抽象值的映射</td><td style="text-align:left;"><code>ρ={a↦3,b↦7}</code></td></tr><tr><td style="text-align:left;">常量传播 / 折叠</td><td style="text-align:left;">constant propagation / folding</td><td style="text-align:left;">判断变量是否为常量 / 将常量表达式替换为计算结果</td><td style="text-align:left;">得出 b=7 / 把 <code>3+4</code> 改成 <code>7</code></td></tr></tbody></table><h2 id="第-06-篇-调用关系与上下文" tabindex="-1"><a class="header-anchor" href="#第-06-篇-调用关系与上下文" aria-hidden="true">#</a> 第 06 篇：调用关系与上下文</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">过程间分析</td><td style="text-align:left;">interprocedural analysis</td><td style="text-align:left;">跨过方法边界、处理调用与返回的分析</td><td style="text-align:left;">追踪 a 经 id 到 b</td></tr><tr><td style="text-align:left;">调用图</td><td style="text-align:left;">call graph</td><td style="text-align:left;">节点是方法，边是“可能调用”</td><td style="text-align:left;">main→id</td></tr><tr><td style="text-align:left;">过程间控制流图</td><td style="text-align:left;">ICFG, interprocedural CFG</td><td style="text-align:left;">把各方法的 CFG 用调用边、返回边缝在一起</td><td style="text-align:left;">A→id 入口，id 出口→retA</td></tr><tr><td style="text-align:left;">调用点 / 返回点</td><td style="text-align:left;">call site / return site</td><td style="text-align:left;">发出调用的位置 / 调用返回后继续执行的位置</td><td style="text-align:left;">A / retA</td></tr><tr><td style="text-align:left;">虚调用</td><td style="text-align:left;">virtual call</td><td style="text-align:left;">实际目标由接收者运行时类型决定的调用</td><td style="text-align:left;"><code>service.read()</code></td></tr><tr><td style="text-align:left;">类层次分析</td><td style="text-align:left;">CHA, class hierarchy analysis</td><td style="text-align:left;">只按声明类型与子类关系确定调用目标</td><td style="text-align:left;"><code>service.read()</code> 得到两个目标</td></tr><tr><td style="text-align:left;">RTA</td><td style="text-align:left;">rapid type analysis</td><td style="text-align:left;">在 CHA 基础上只保留程序中实际实例化的类</td><td style="text-align:left;">去掉从未 <code>new</code> 的 NetReader</td></tr><tr><td style="text-align:left;">基于指向的调用图</td><td style="text-align:left;">points-to-based call graph</td><td style="text-align:left;">先算变量指向哪些对象，再确定目标</td><td style="text-align:left;">收缩为 <code>FileReader.read</code></td></tr><tr><td style="text-align:left;">上下文敏感</td><td style="text-align:left;">context-sensitive</td><td style="text-align:left;">区分同一方法在不同调用处的分析结果</td><td style="text-align:left;">A 的返回不污染 B 的 c</td></tr><tr><td style="text-align:left;">流敏感</td><td style="text-align:left;">flow-sensitive</td><td style="text-align:left;">区分语句顺序</td><td style="text-align:left;"><code>x=input(); x=&quot;safe&quot;;</code> 后 x 干净</td></tr><tr><td style="text-align:left;">路径敏感（06 的例子）</td><td style="text-align:left;">path-sensitive</td><td style="text-align:left;">区分分支条件及其关联，定义见第 01 篇</td><td style="text-align:left;"><code>if (flag) … if (!flag) sink(y)</code></td></tr><tr><td style="text-align:left;">调用到返回边 / 旁路</td><td style="text-align:left;">call-to-return edge</td><td style="text-align:left;">调用者中不经被调方法传播的事实所走的边</td><td style="text-align:left;">执行 A 时 a 的污点直接保留</td></tr><tr><td style="text-align:left;">摘要</td><td style="text-align:left;">summary</td><td style="text-align:left;">方法输入对输出影响的可复用记录</td><td style="text-align:left;">id：入口 p 有污点则返回值有污点</td></tr><tr><td style="text-align:left;">净化</td><td style="text-align:left;">sanitizer</td><td style="text-align:left;">按约定消除污点的操作</td><td style="text-align:left;"><code>escape(x)</code></td></tr><tr><td style="text-align:left;">隐式流</td><td style="text-align:left;">implicit flow</td><td style="text-align:left;">值通过条件判断而非赋值影响另一变量</td><td style="text-align:left;"><code>if (x.equals(&quot;a&quot;)) y=&quot;a&quot;;</code></td></tr></tbody></table><h2 id="第-07-篇-ifds-事实传播" tabindex="-1"><a class="header-anchor" href="#第-07-篇-ifds-事实传播" aria-hidden="true">#</a> 第 07 篇：IFDS 事实传播</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">IFDS</td><td style="text-align:left;">Interprocedural Finite Distributive Subset</td><td style="text-align:left;">满足分配律的有限事实集合问题的过程间求解框架</td><td style="text-align:left;">本系列的污点传播</td></tr><tr><td style="text-align:left;">流函数</td><td style="text-align:left;">flow function</td><td style="text-align:left;">IFDS 文献对转移函数的叫法</td><td style="text-align:left;"><code>y=x</code> 的流函数</td></tr><tr><td style="text-align:left;">分配律</td><td style="text-align:left;">distributivity</td><td style="text-align:left;">先合并再转移与分别转移再合并结果相同</td><td style="text-align:left;"><code>f(A∪B)=f(A)∪f(B)</code></td></tr><tr><td style="text-align:left;">辅助事实 Λ</td><td style="text-align:left;">zero fact, Λ</td><td style="text-align:left;">表示“无条件成立”的人为事实，用来生成新事实</td><td style="text-align:left;"><code>Λ→x</code> 表示 <code>x=input()</code></td></tr><tr><td style="text-align:left;">表示关系</td><td style="text-align:left;">representation relation</td><td style="text-align:left;">一条语句的流函数拆成的单事实边集合</td><td style="text-align:left;"><code>y=x</code>：<code>x→x</code>、<code>x→y</code></td></tr><tr><td style="text-align:left;">爆炸超图</td><td style="text-align:left;">ESG, exploded supergraph</td><td style="text-align:left;">节点是 <code>(程序点, 事实)</code>，边是单事实传播</td><td style="text-align:left;"><code>(A 之前, a) → (entry, p)</code></td></tr><tr><td style="text-align:left;">四类流函数</td><td style="text-align:left;">normal / call / return / call-to-return</td><td style="text-align:left;">方法内 / 实参到形参 / 返回值到接收变量 / 旁路</td><td style="text-align:left;">见第 07 篇第 5 节表</td></tr><tr><td style="text-align:left;">路径边</td><td style="text-align:left;">path edge</td><td style="text-align:left;">“从方法入口带着 d₁ 进来，现在在 n 处是 d₂”</td><td style="text-align:left;"><code>〈p, exit, ret〉</code></td></tr><tr><td style="text-align:left;">Incoming</td><td style="text-align:left;">incoming</td><td style="text-align:left;">等待某个被调入口事实结果的调用记录</td><td style="text-align:left;">A 等待 <code>(id, p)</code></td></tr><tr><td style="text-align:left;">出口摘要 Summary</td><td style="text-align:left;">summary edge</td><td style="text-align:left;">某入口事实能产生哪些出口事实；到达出口的路径边</td><td style="text-align:left;"><code>p→ret</code></td></tr><tr><td style="text-align:left;">tabulation 算法</td><td style="text-align:left;">tabulation</td><td style="text-align:left;">IFDS 的求解算法，逐条登记路径边与摘要</td><td style="text-align:left;">第 07 篇第 7 节伪代码</td></tr><tr><td style="text-align:left;">可实现路径</td><td style="text-align:left;">realizable path</td><td style="text-align:left;">每次返回都回到匹配调用点的路径，允许有尚未返回的调用</td><td style="text-align:left;">A 进 id 必须回到 retA</td></tr><tr><td style="text-align:left;">MRP / MOP</td><td style="text-align:left;">meet over all realizable / all paths</td><td style="text-align:left;">只沿可实现路径合并 / 沿所有路径合并</td><td style="text-align:left;">IFDS 求的是 MRP，分配律成立时精确等于它</td></tr><tr><td style="text-align:left;">CFL 可达性</td><td style="text-align:left;">CFL-reachability</td><td style="text-align:left;">路径上标签串须属于某个上下文无关语言</td><td style="text-align:left;">调用返回的括号匹配</td></tr></tbody></table><h2 id="第-08-篇-ide-值传播" tabindex="-1"><a class="header-anchor" href="#第-08-篇-ide-值传播" aria-hidden="true">#</a> 第 08 篇：IDE 值传播</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">IDE</td><td style="text-align:left;">Interprocedural Distributive Environments</td><td style="text-align:left;">在 IFDS 的事实边上附加值变换</td><td style="text-align:left;">求 u=15、v=30</td></tr><tr><td style="text-align:left;">边函数</td><td style="text-align:left;">edge function</td><td style="text-align:left;">一条事实边上值怎样变</td><td style="text-align:left;"><code>t↦t+2</code></td></tr><tr><td style="text-align:left;">跳转函数</td><td style="text-align:left;">jump function</td><td style="text-align:left;">从方法入口到目标事实，沿路径组合边函数、再合并路径所得的变换</td><td style="text-align:left;"><code>〈p, exit, ret, t↦5(t+2)〉</code></td></tr><tr><td style="text-align:left;">函数组合</td><td style="text-align:left;">composition, ∘</td><td style="text-align:left;">先做 f 再做 g 写作 <code>g∘f</code></td><td style="text-align:left;"><code>5(t+2)</code></td></tr><tr><td style="text-align:left;">逐点合并</td><td style="text-align:left;">pointwise join</td><td style="text-align:left;">两条路径的函数在每个输入上分别 Join</td><td style="text-align:left;"><code>(j₁ ⊔ j₂)(t) = j₁(t) ⊔ j₂(t)</code></td></tr><tr><td style="text-align:left;">线性常量传播</td><td style="text-align:left;">linear constant propagation</td><td style="text-align:left;">解释常量、复制和一元线性赋值的常量传播，函数表示须支持组合与合并</td><td style="text-align:left;">calc 的加 2、乘 5</td></tr><tr><td style="text-align:left;">两阶段求解</td><td style="text-align:left;">phase I / phase II</td><td style="text-align:left;">先算稳定的跳转函数，再代入入口值</td><td style="text-align:left;">先得 j，再算 j(1)、j(4)</td></tr></tbody></table><h2 id="第-09-篇-符号执行与-clang" tabindex="-1"><a class="header-anchor" href="#第-09-篇-符号执行与-clang" aria-hidden="true">#</a> 第 09 篇：符号执行与 Clang</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">符号执行</td><td style="text-align:left;">symbolic execution</td><td style="text-align:left;">用符号值代替未知输入、沿路径累积条件的分析方式</td><td style="text-align:left;">本篇整体</td></tr><tr><td style="text-align:left;">符号值</td><td style="text-align:left;">symbolic value</td><td style="text-align:left;">不知道具体值时先起的名字</td><td style="text-align:left;">β 表示 flag 的值</td></tr><tr><td style="text-align:left;">路径条件</td><td style="text-align:left;">path condition</td><td style="text-align:left;">走到当前位置必须满足的约束合取</td><td style="text-align:left;"><code>β ∧ ¬β</code></td></tr><tr><td style="text-align:left;">不可行路径</td><td style="text-align:left;">infeasible path</td><td style="text-align:left;">路径条件不可满足的路径</td><td style="text-align:left;">带污点进入 sink 的那条</td></tr><tr><td style="text-align:left;">ProgramState / ExplodedNode / ExplodedGraph</td><td style="text-align:left;">—</td><td style="text-align:left;">Clang 中一条路径的状态 / “位置加状态”的节点 / 由这些节点组成的探索图</td><td style="text-align:left;">见第 09 篇第 4 节表</td></tr></tbody></table><h2 id="第-10-篇-ide-求解器工程优化" tabindex="-1"><a class="header-anchor" href="#第-10-篇-ide-求解器工程优化" aria-hidden="true">#</a> 第 10 篇：IDE 求解器工程优化</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">跳转函数表布局</td><td style="text-align:left;">jump function layout</td><td style="text-align:left;">用什么嵌套结构存 <code>(n,d₁,d₂)→f</code></td><td style="text-align:left;">JF_ND、JF_N</td></tr><tr><td style="text-align:left;">批处理</td><td style="text-align:left;">batching</td><td style="text-align:left;">固定外层键后一次处理多条更新</td><td style="text-align:left;">复用 <code>table[n]</code></td></tr><tr><td style="text-align:left;">回收（条目回收，GC）</td><td style="text-align:left;">garbage collection of jump functions</td><td style="text-align:left;">方法内部条目在确认不再需要后释放；源自 Arzt 2021</td><td style="text-align:left;">保留 <code>p→ret</code>，回收 <code>p→a</code></td></tr><tr><td style="text-align:left;">感兴趣节点</td><td style="text-align:left;">interesting nodes</td><td style="text-align:left;">客户端要查询值、因此不能回收的程序点</td><td style="text-align:left;">类型状态分析的状态转移语句</td></tr><tr><td style="text-align:left;">稀疏化</td><td style="text-align:left;">sparse analysis</td><td style="text-align:left;">事实只在定义与使用之间传播</td><td style="text-align:left;">He 等 2020 对 IFDS 的稀疏化</td></tr><tr><td style="text-align:left;">按需求解</td><td style="text-align:left;">demand-driven analysis</td><td style="text-align:left;">只从查询点出发探索</td><td style="text-align:left;">Boomerang</td></tr></tbody></table><h2 id="第-11-篇-对象、别名与指针分析" tabindex="-1"><a class="header-anchor" href="#第-11-篇-对象、别名与指针分析" aria-hidden="true">#</a> 第 11 篇：对象、别名与指针分析</h2><table><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">英文</th><th style="text-align:left;">一句话解释</th><th style="text-align:left;">在例子中</th></tr></thead><tbody><tr><td style="text-align:left;">指针分析 / 指向分析</td><td style="text-align:left;">pointer analysis / points-to analysis</td><td style="text-align:left;">计算每个引用变量可能指向哪些对象</td><td style="text-align:left;">判断 a、b 是否指向同一个 Holder</td></tr><tr><td style="text-align:left;">分配点抽象</td><td style="text-align:left;">allocation-site abstraction</td><td style="text-align:left;">用每处 <code>new</code> 代表它创建的全部对象</td><td style="text-align:left;"><code>new Holder()</code> 记为 o1</td></tr><tr><td style="text-align:left;">抽象对象 / 堆抽象</td><td style="text-align:left;">abstract object / heap abstraction</td><td style="text-align:left;">分析中代表一组运行时对象的记号及其划分方式</td><td style="text-align:left;">o1、s</td></tr><tr><td style="text-align:left;">指向集合</td><td style="text-align:left;">points-to set, pts(x)</td><td style="text-align:left;">x 可能指向的抽象对象集合</td><td style="text-align:left;"><code>pts(b)={o1}</code></td></tr><tr><td style="text-align:left;">可能别名</td><td style="text-align:left;">may alias</td><td style="text-align:left;">两个变量的指向集合有交集</td><td style="text-align:left;">a、b 都含 o1</td></tr><tr><td style="text-align:left;">Andersen 式 / 基于包含</td><td style="text-align:left;">Andersen-style / inclusion-based</td><td style="text-align:left;">用 <code>⊆</code> 约束表达 new、copy、store、load 四类语句</td><td style="text-align:left;"><code>pts(a) ⊆ pts(b)</code></td></tr><tr><td style="text-align:left;">基于等价</td><td style="text-align:left;">equality-based (Steensgaard)</td><td style="text-align:left;">把拷贝两端合并为一个节点，快但粗</td><td style="text-align:left;">未采用</td></tr><tr><td style="text-align:left;">流不敏感</td><td style="text-align:left;">flow-insensitive</td><td style="text-align:left;">忽略语句顺序，所有语句作为同时成立的约束</td><td style="text-align:left;"><code>b=a</code> 前后位置不影响结果</td></tr><tr><td style="text-align:left;">字段敏感</td><td style="text-align:left;">field-sensitive</td><td style="text-align:left;">区分同一对象的不同字段</td><td style="text-align:left;"><code>o1.f</code> 有自己的集合</td></tr><tr><td style="text-align:left;">on-the-fly 调用图</td><td style="text-align:left;">on-the-fly call graph</td><td style="text-align:left;">求解指向集合的同时按新到达对象的类型添加调用边</td><td style="text-align:left;"><code>service.read()</code> 只连到 FileReader.read</td></tr><tr><td style="text-align:left;">上下文敏感堆</td><td style="text-align:left;">context-sensitive heap / heap cloning</td><td style="text-align:left;">分配点也带上下文，区分同一 <code>new</code> 在不同上下文创建的对象</td><td style="text-align:left;"><code>o3[A]</code>、<code>o3[B]</code></td></tr><tr><td style="text-align:left;">调用点敏感</td><td style="text-align:left;">call-site sensitivity, k-CFA</td><td style="text-align:left;">用最近 k 层调用点作方法的上下文</td><td style="text-align:left;"><code>make[A]</code>、<code>make[B]</code></td></tr><tr><td style="text-align:left;">对象敏感</td><td style="text-align:left;">object sensitivity</td><td style="text-align:left;">用接收者对象的分配点作方法的上下文</td><td style="text-align:left;"><code>set[o4]</code>、<code>set[o5]</code></td></tr><tr><td style="text-align:left;">混合上下文敏感</td><td style="text-align:left;">hybrid context-sensitivity</td><td style="text-align:left;">虚调用用对象上下文，静态调用用调用点上下文</td><td style="text-align:left;">静态 <code>fill</code> 用调用点、<code>set</code> 用接收者</td></tr><tr><td style="text-align:left;">按需求解（别名）</td><td style="text-align:left;">demand-driven alias analysis</td><td style="text-align:left;">从查询点出发只求解相关的字段与调用括号匹配</td><td style="text-align:left;">Boomerang</td></tr><tr><td style="text-align:left;">差分传播</td><td style="text-align:left;">difference propagation</td><td style="text-align:left;">工作列表只传播新到达的对象，不重传整个集合</td><td style="text-align:left;">第 11 篇第 3.4 节伪代码</td></tr><tr><td style="text-align:left;">Spark</td><td style="text-align:left;">—</td><td style="text-align:left;">Soot 的 Andersen 式指向分析实现</td><td style="text-align:left;">第 11 篇第 7 节的输出</td></tr></tbody></table>',18);function c(h,u){const d=i("RouterLink");return n(),s("div",null,[g,r,o,t("p",null,[y(d,{to:"/static-analysis/"},{default:f(()=>[e("返回系列总览")]),_:1})])])}const m=a(x,[["render",c],["__file","99-glossary.html.vue"]]);export{m as default};
